command:
// ==========================================
// LUNAS WIRKUNG: MAUNZENDER BEFEHL (BRONA)
//
// - genau ein Ziel
// - Zielkategorie: Menschen
// - Zweibeiner als vorhandene Erkennungsalternative
// - Reichweite: 8 Schritt
// - Dauer: QS Minuten
// - sichtbarer Effekt auf dem Ziel
// - keine Gefährdung des Ziels oder seiner Liebsten
// - gespeichertes Ziel ohne neues GM-Target
// - Effektanlage über Block 6
// - Wirkungsende über Block 7
// - öffentliche Karte + „Effekt anwenden“
// ==========================================

(async function () {
const macroUuid = this?.uuid || game.macros.getName("Maunzender Befehl")?.uuid || null;

// +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++++++

const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
const frameworkFehlt =
    !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register ||
    !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde ||
    !globalThis.DSK?.Target?.Merken || !globalThis.DSK?.Target?.Finden ||
    !globalThis.DSK?.Target?.Actor || !globalThis.DSK?.Geometrie?.Distanz ||
    !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
    !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
    !globalThis.DSK?.GabenUI?.GMMakroButton ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
    !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

if (frameworkFehlt) {
    const fwMacro = await fromUuid(frameworkUuid);

    if (!fwMacro?.execute) {
        return ui.notifications.error(
            "Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!"
        );
    }

    await fwMacro.execute();
    await new Promise(resolve => setTimeout(resolve, 150));
}

const DSK_FW = globalThis.DSK;

if (
    !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
    !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
    !DSK_FW?.Target?.Merken || !DSK_FW?.Target?.Finden ||
    !DSK_FW?.Target?.Actor || !DSK_FW?.Geometrie?.Distanz ||
    !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden ||
    !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen ||
    !DSK_FW?.GabenUI?.GMMakroButton ||
    !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
    !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
) {
    return ui.notifications.error(
        "Luna sagt 🌙: Das DSK-Framework 01.02 wurde nicht vollständig geladen!"
    );
}

// +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++++++

const gabenName = "Maunzender Befehl", vollerName = "Maunzender Befehl (Brona)", ahne = "Brona";
const flagKey = "pendingMaunzenderBefehlBrona", endeKey = "bronaMaunzenderBefehl";
const reichweite = 8;
const endeText =
    "Der zwingende Einfluss des Maunzens endet. Das Ziel kann wieder frei über seine Handlungen entscheiden.";

DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

// +++ 3 - HELFER ++++++++++++++++++++++++++++++++++++++++++++++

const raeumeQSAuf = async actor => {
    if (actor?.getFlag("world", "letzteGabenQS") !== undefined) {
        await actor.unsetFlag("world", "letzteGabenQS");
    }

    if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) {
        await actor.unsetFlag("world", "letzteGabenMessageId");
    }
};

const istMensch = actor => {
    if (!actor) return false;

    const spezies = String(
        actor.system?.details?.species?.value ||
        actor.system?.details?.species ||
        actor.system?.species?.value ||
        actor.system?.species ||
        ""
    ).toLowerCase();

    return (
        spezies.includes("mensch") ||
        spezies.includes("zweibeiner")
    );
};

const ladeZiel = async daten => {
    if (!daten) return { token: null, actor: null };

    const token = await DSK_FW.Target.Finden(daten);

    return {
        token,
        actor: token?.actor || await DSK_FW.Target.Actor(daten)
    };
};

const findeEigeneEffekte = (actor, casterUuid) =>
    (actor?.effects || []).filter(effect =>
        (effect.name || effect.label || "") === vollerName &&
        effect.getFlag("dsk", "isMaunzenderBefehl") === true &&
        effect.getFlag("dsk", "casterUuid") === casterUuid
    );

const beschreibungFuer = (casterName, targetName) =>
    `<b>${casterName}</b> maunzt <b>${targetName}</b> befehlend an.` +
    `<br><br>Der Mensch führt eine kommunizierte Handlung aus, von der das Ziel glaubt, dass die Vampirkatze diese Handlung erwartet.` +
    `<br><br><b style="color:#B30000;">Grenze:</b> Der Befehl darf weder das Ziel noch dessen Liebste gefährden.` +
    `<br><b>Zielkategorie:</b> Menschen` +
    `<br><b>Reichweite:</b> ${reichweite} Schritt`;

// +++ 4 - EFFEKT AUF ZIEL ANWENDEN ++++++++++++++++++++++++++++

const wendeEffektAn = async ({
    casterActor,
    casterName,
    targetActor,
    targetName,
    qs
}) => {
    if (!casterActor || !targetActor || !istMensch(targetActor)) {
        return false;
    }

    const alteEffekte = findeEigeneEffekte(
        targetActor,
        casterActor.uuid
    );

    if (alteEffekte.length) {
        await targetActor.deleteEmbeddedDocuments(
            "ActiveEffect",
            alteEffekte.map(effect => effect.id)
        );
    }

    const effekt = await DSK_FW.Effekt.Anwenden({
        name: vollerName,
        ahne,

        beschreibung:
            `<b>${targetName}</b> steht unter dem Einfluss des maunzenden Befehls von <b>${casterName}</b>.` +
            `<br><br>Das Ziel führt die kommunizierte Handlung aus, sofern diese weder das Ziel noch dessen Liebste gefährdet.` +
            `<br><b>Wirkungsdauer:</b> ${qs} Minuten`,

        gabeZiel: "",
        qs,
        ziel: targetActor,

        duration: {
            seconds: qs * 60,
            startTime: game.time.worldTime
        },

        showIcon: 1,

        flags: {
            dsk: {
                isMaunzenderBefehl: true,
                casterUuid: casterActor.uuid,
                casterName,
                qs,
                reichweite,

                wirkungsende: {
                    sfName: endeKey,
                    basisEffektName: vollerName,
                    beschreibungFuerEnde: endeText
                }
            }
        }
    });

    if (!effekt) return false;

    const endeDaten =
        effekt.getFlag("dsk", "wirkungsende");

    return Boolean(
        (effekt.name || effekt.label || "") === vollerName &&
        effekt.parent?.uuid === targetActor.uuid &&
        effekt.getFlag("dsk", "isMaunzenderBefehl") === true &&
        effekt.getFlag("dsk", "casterUuid") === casterActor.uuid &&
        Number(effekt.getFlag("dsk", "qs")) === qs &&
        Number(effekt.getFlag("dsk", "reichweite")) === reichweite &&
        endeDaten?.sfName === endeKey &&
        endeDaten?.basisEffektName === vollerName &&
        endeDaten?.beschreibungFuerEnde === endeText
    );
};

// +++ 5 - GM-ANFRAGE VERARBEITEN +++++++++++++++++++++++++++++

const verarbeiteAnfrage = async (casterActor, daten) => {
    if (!game.user.isGM || !casterActor || !daten) return false;

    if (
        daten.casterUuid &&
        daten.casterUuid !== casterActor.uuid
    ) {
        ui.notifications.warn(
            "Luna sagt 🌙: Die gespeicherte Anfrage passt nicht zum Wirkenden."
        );

        return false;
    }

    if (
        daten.sceneId &&
        daten.sceneId !== canvas.scene?.id
    ) {
        ui.notifications.warn(
            `Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`
        );

        return false;
    }

    const casterToken = DSK_FW.Token.Finde(
        casterActor,
        daten.casterTokenId,
        daten.casterTokenUuid
    );

    if (!casterToken) {
        ui.notifications.warn(
            `Luna sagt 🌙: Der Token von „${casterActor.name}“ wurde nicht gefunden!`
        );

        return false;
    }

    const {
        token: targetToken,
        actor: targetActor
    } = await ladeZiel(daten.target);

    const qs = Math.max(
        1,
        Math.floor(Number(daten.qs) || 1)
    );

    const casterName =
        daten.casterName ||
        DSK_FW.ResolveTokenName(casterActor);

    const targetName =
        daten.target?.name ||
        targetToken?.name ||
        targetActor?.name ||
        "Unbekanntes Ziel";

    const weiterhinGueltig = Boolean(
        targetToken &&
        targetActor &&
        istMensch(targetActor) &&
        DSK_FW.Geometrie.Distanz(casterToken, targetToken) <= reichweite
    );

    let erfolgreich = false;

    if (weiterhinGueltig) {
        try {
            erfolgreich = await wendeEffektAn({
                casterActor,
                casterName,
                targetActor,
                targetName,
                qs
            });
        } catch (error) {
            console.error(
                "Maunzender Befehl: Effektanlage fehlgeschlagen.",
                {
                    targetActor,
                    error
                }
            );
        }
    }

    await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
        messageId: daten.messageId,
        gabenName: vollerName,
        ahne,

        beschreibung:
            daten.beschreibung ||
            beschreibungFuer(casterName, targetName),

        wirkender: casterName,

        ziele: erfolgreich
            ? [{
                name: targetName,
                rolle: "Befehlsempfänger"
            }]
            : [],

        misserfolge: erfolgreich
            ? []
            : [{
                name: targetName
            }],

        dauerText: `${qs} Minuten`,
        erfolgreich
    });

    if (erfolgreich) {
        ui.notifications.info(
            `Luna sagt 🌙: ${targetName} steht für ${qs} Minuten unter dem maunzenden Befehl.`
        );
    } else {
        ui.notifications.error(
            "Luna sagt 🌙: Maunzender Befehl konnte nicht angewendet werden!"
        );
    }

    return true;
};

// +++ 6 - GM-MODUS ++++++++++++++++++++++++++++++++++++++++++++

if (game.user.isGM) {
    const anfragen =
        DSK_FW.GMAnfrage.Finden(flagKey);

    if (anfragen.length) {
        for (const anfrageActor of anfragen) {
            const daten =
                DSK_FW.GMAnfrage.Lesen(
                    anfrageActor,
                    flagKey
                );

            if (!daten) continue;

            if (
                await verarbeiteAnfrage(
                    anfrageActor,
                    daten
                )
            ) {
                await DSK_FW.GMAnfrage.Loeschen(
                    anfrageActor,
                    flagKey
                );
            }
        }

        return;
    }
}

// +++ 7 - WIRKENDER UND QS ++++++++++++++++++++++++++++++++++++

let casterActor =
    canvas.tokens.controlled[0]?.actor ||
    game.user.character ||
    null;

if (!casterActor) {
    casterActor =
        canvas.tokens.placeables
            .map(token => token.actor)
            .find(actor =>
                actor?.getFlag(
                    "world",
                    "letzteGabenQS"
                ) !== undefined
            ) ||
        game.actors.find(actor =>
            actor.getFlag(
                "world",
                "letzteGabenQS"
            ) !== undefined
        ) ||
        null;
}

if (!casterActor) {
    return ui.notifications.warn(
        "Luna sagt 🌙: Kein Wirkender gefunden!"
    );
}

if (
    !game.user.isGM &&
    !casterActor.isOwner
) {
    return ui.notifications.warn(
        "Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!"
    );
}

const casterToken =
    DSK_FW.Token.Finde(casterActor);

if (!casterToken) {
    return ui.notifications.warn(
        "Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!"
    );
}

const casterName =
    DSK_FW.ResolveTokenName(casterActor);

const qs =
    DSK_FW.QS.Ermitteln({
        actor: casterActor,
        gabenName,

        suchbegriffe: [
            "Maunzender Befehl Probe",
            "Maunzender Befehl"
        ],

        testDataObj:
            typeof testData !== "undefined"
                ? testData
                : null,

        fallback: 0,
        protokollieren: true
    });

if (qs <= 0) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName,
        ahne,
        beschreibung:
            "Der maunzende Befehl konnte seinen zwingenden Einfluss nicht entfalten.",
        wirkender: casterName,
        ziele: [],
        misserfolge: [{
            name: casterName
        }],
        dauerText: "0 Minuten",
        gmBereich: false,
        angewendet: true,
        erfolgreich: false,
        anfragenderUserId: game.user.id
    });

    await raeumeQSAuf(casterActor);
    return;
}

// +++ 8 - GENAU EIN ZIEL PRÜFEN +++++++++++++++++++++++++++++++

const targets =
    Array.from(
        game.user.targets || []
    );

if (targets.length !== 1) {
    await raeumeQSAuf(casterActor);

    return ui.notifications.warn(
        "Luna sagt 🌙: Bitte wähle genau ein Ziel für Maunzender Befehl!"
    );
}

const targetToken =
    targets[0];

const targetActor =
    targetToken?.actor;

const targetName =
    targetToken?.name ||
    targetActor?.name ||
    "Unbekanntes Ziel";

const distanz =
    targetActor
        ? DSK_FW.Geometrie.Distanz(
            casterToken,
            targetToken
        )
        : Infinity;

const gueltig = Boolean(
    targetActor &&
    istMensch(targetActor) &&
    distanz <= reichweite
);

const beschreibung =
    beschreibungFuer(
        casterName,
        targetName
    );

if (!gueltig) {
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName,
        ahne,
        beschreibung,
        wirkender: casterName,
        ziele: [],
        misserfolge: [{
            name: targetName
        }],
        dauerText: `${qs} Minuten`,
        gmBereich: false,
        angewendet: true,
        erfolgreich: false,
        anfragenderUserId: game.user.id
    });

    await raeumeQSAuf(casterActor);
    return;
}

const targetDaten =
    DSK_FW.Target.Merken(
        targetToken
    );

if (!targetDaten) {
    await raeumeQSAuf(casterActor);

    return ui.notifications.error(
        "Luna sagt 🌙: Das Ziel konnte nicht gespeichert werden!"
    );
}

// +++ 9 - GEMEINSAME KARTE + GM-ANFRAGE +++++++++++++++++++++++

const gmLink =
    DSK_FW.GabenUI.GMMakroButton(
        macroUuid,
        "Effekt anwenden",
        "Das Makro muss durch die Spielleitung ausgeführt werden."
    );

const nachricht =
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName,
        ahne,
        beschreibung,
        wirkender: casterName,

        ziele: [{
            name: targetName,
            rolle: "Befehlsempfänger"
        }],

        misserfolge: [],
        dauerText: `${qs} Minuten`,
        gmLink,
        gmBereich: !game.user.isGM,
        anfragenderUserId: game.user.id
    });

if (!nachricht) {
    await raeumeQSAuf(casterActor);

    return ui.notifications.error(
        "Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!"
    );
}

const anfrageDaten = {
    casterUuid: casterActor.uuid,
    casterName,

    casterTokenId: casterToken.id,
    casterTokenUuid:
        casterToken.document?.uuid ||
        casterToken.uuid ||
        null,

    target: targetDaten,
    qs,
    beschreibung,

    sceneId:
        canvas.scene?.id ||
        null,

    requestedByUserId:
        game.user.id,

    messageId:
        nachricht.id,

    macroUuid,
    erstellt: Date.now()
};

// +++ 10 - DIREKT ODER GM-ANFRAGE +++++++++++++++++++++++++++++

if (game.user.isGM) {
    await verarbeiteAnfrage(
        casterActor,
        anfrageDaten
    );

    await raeumeQSAuf(
        casterActor
    );

    return;
}

await DSK_FW.GMAnfrage.Speichern(
    casterActor,
    flagKey,
    anfrageDaten
);

await raeumeQSAuf(
    casterActor
);

ui.notifications.info(
    "Luna sagt 🌙: Maunzender Befehl wurde bei der Spielleitung zur Anwendung beantragt."
);

}).call(this);
